static NSString *ZPBase(const char *p){ if(!p)return @"?"; const char *s=strrchr(p,'/'); return [NSString stringWithUTF8String:s?s+1:p]?:@"?"; }
static NSString *ZPHex(const uint8_t *b,size_t n){ NSMutableString *s=[NSMutableString stringWithCapacity:n*2]; for(size_t i=0;i<n;i++)[s appendFormat:@"%02X",b[i]]; return s; }
