static NSArray<NSNumber*> *ZPFindDecryptCandidates(uintptr_t start,uintptr_t end){
    NSMutableArray *out=[NSMutableArray array]; if(!start||end<=start)return out; const uint32_t a=0xD105C3FFu,b=0xB9400408u,c=0x53187D00u; for(uintptr_t p=start;p+0x44<=end;p+=4){ uint32_t x=0,y=0,z=0; memcpy(&x,(const void*)p,4); if(x!=a)continue; memcpy(&y,(const void*)(p+0x30),4); if(y!=b)continue; memcpy(&z,(const void*)(p+0x40),4); if(z!=c)continue; [out addObject:@(p)]; if(out.count>=16)break; } return out;
