static BOOL ZPNumericASCII(const uint8_t *bytes,size_t len,unsigned long long *valueOut,NSString **textOut){ if(!bytes||!len||len>64)return NO; char tmp[65]={0}; size_t n=MIN(len,(size_t)64); memcpy(tmp,bytes,n); while(n&&isspace((unsigned char)tmp[n-1]))tmp[--n]=0; size_t i=0; while(i<n&&isspace((unsigned char)tmp[i]))i++; if(i>=n)return NO; for(size_t j=i;j<n;j++)if(tmp[j]&&(!isprint((unsigned char)tmp[j])))return NO; errno=0; char *end=NULL; unsigned long long v=strtoull(tmp+i,&end,0); if(errno||end==tmp+i)return NO; while(end&&*end&&isspace((unsigned char)*end))end++; if(end&&*end)return NO; if(valueOut)*valueOut=v; if(textOut)*textOut=[NSString stringWithUTF8String:tmp+i]; return YES; }
static BOOL ZPClassChainContains(id object,const char *needle){ for(Class c=object?object_getClass(object):Nil;c;c=class_getSuperclass(c)){ const char *n=class_getName(c); if(n&&strstr(n,needle))return YES; } return NO; }
