void ZPLegacyOffsetResolverSchedule(id wrapper,NSString *identifier,NSDictionary *feature,NSString *expectedImage){ if(!wrapper||!identifier.length)return; id retained=wrapper; NSString *iid=[identifier copy],*img=[expectedImage copy]; NSDictionary *f=[feature copy]; dispatch_async(ZPOffsetQueue(),^{@autoreleasepool{ZPResolve(retained,iid,f,img);}}); }
